import{CITY as g,WATER_Y as x,shoreZ as A,groundY as P,blockAt as y,piers as k,isLand as M,seeded as d}from"./city.min.js";const b=6e4;export const LIFE={ferry:{cycle:100,crossing:35,lane:70,length:140,scale:1.2},ship:{every:75,offset:20,speed:7,span:4e4,lanes:{north:-6300,south:-6900},length:290},sailboat:{count:6,from:8,to:19.5,scale:2},seaplane:{takeoff:20,landing:50,from:8,to:19,run:35,climb:150,top:45,rise:4,scale:2},cars:{count:240,speed:[8,14],near:{x0:-200,x1:120,z1:-6}},wind:6,ripple:[.004,.0025]};export function minutesOn(t){return t.getTime()/b}export function minutesOfDay(t){return t.getHours()*60+t.getMinutes()+t.getSeconds()/60+t.getMilliseconds()/b}export function gently(t){const n=Math.min(1,Math.max(0,t));return n-Math.sin(2*Math.PI*n)/(2*Math.PI)}export function yawFor(t,n){return Math.atan2(-t,-n)}export function ferryRoute(t=g){const n=k(t).find(l=>l.ferry),a=n.x,s=n.z-n.length-LIFE.ferry.length/2;let i=s;for(;!M(a,i,t)&&i>-4e4;)i-=10;return{x:a,from:s,to:i+LIFE.ferry.length/2+60}}export function ferriesAt(t,n=ferryRoute()){const{cycle:a,crossing:s,lane:i}=LIFE.ferry,l=a/2;return[0,1].map(r=>{const c=((minutesOn(t)+r*l)%a+a)%a,o=c<l,e=(o?c:c-l)/s,f=gently(e),h=o?f:1-f,p=o?1:-1,u=n.x+p*i*Math.sin(Math.PI*f),m=n.from+(n.to-n.from)*h,w=e>0&&e<1?(1-Math.cos(2*Math.PI*e))/2:0,z=o?-1:1,I=p*i*Math.PI*Math.cos(Math.PI*f)/Math.abs(n.to-n.from);return{x:u,y:x,z:m,yaw:yawFor(I,z),speed:w}})}export function shipsAt(t){const{every:n,offset:a,speed:s,span:i,lanes:l}=LIFE.ship,r=minutesOn(t),c=[],o=i/s/60;for(let e=Math.floor((r-a-o)/n);e<=Math.ceil((r-a+o)/n);e++){const f=e*n+a,h=(e%2+2)%2===0,p=(h?1:-1)*s*(r-f)*60;Math.abs(p)>i||c.push({k:e,x:p,y:x,z:h?l.north:l.south,yaw:yawFor(h?1:-1,0),speed:1})}return c}export function sailboatCourses(t=20260927){const n=d(t);return Array.from({length:LIFE.sailboat.count},()=>({cx:-1400+n()*3e3,cz:-2300-n()*1500,a:220+n()*280,b:140+n()*200,period:18+n()*20,phase:n(),heel:(8+n()*8)*(Math.PI/180)}))}export function sailboatsAt(t,n=sailboatCourses(),a=0){const s=minutesOfDay(t),i=s>=LIFE.sailboat.from*60&&s<=LIFE.sailboat.to*60&&a<.3,l=minutesOn(t);return n.map(r=>{const c=2*Math.PI*(l/r.period+r.phase),o=r.cx+r.a*Math.cos(c),e=r.cz+r.b*Math.sin(c);return{x:o,y:x,z:e,yaw:yawFor(-r.a*Math.sin(c),r.b*Math.cos(c)),heel:r.heel,out:i}})}export const SEAPLANE_START=[900,-1500];export function takeoff(t){const{run:n,climb:a,top:s,rise:i}=LIFE.seaplane;if(t<0||t>n+a)return null;const[l,r]=SEAPLANE_START,c=s/n;if(t<=n)return{x:l,y:x,z:r-.5*c*t*t,yaw:0,pitch:0,speed:t/n};const o=t-n;return{x:l,y:x+i*o,z:r-.5*c*n*n-s*o,yaw:0,pitch:Math.atan2(i,s),speed:1}}export function seaplaneAt(t,n=0){const{takeoff:a,landing:s,from:i,to:l,run:r,climb:c}=LIFE.seaplane,o={x:SEAPLANE_START[0],y:x,z:SEAPLANE_START[1],yaw:0,pitch:0,speed:0},e=minutesOfDay(t),f=Math.floor(e/60);if(f<i||f>l||n>.5)return o;const h=(e-f*60)*60,p=r+c;if(h<a*60)return o;if(h<=a*60+p)return takeoff(h-a*60);if(h<s*60)return null;if(h>s*60+p)return o;const u=takeoff(Math.max(0,p-(h-s*60)));return{...u,yaw:Math.PI,pitch:u.y>x?.04:0}}export function carLanes(t=g){const{x0:n,x1:a,z1:s}=LIFE.cars.near,i=t.street/2,l=[],r=(o,e)=>{Math.hypot(e[0]-o[0],e[2]-o[2])>40&&l.push({a:o,b:e})},c=(o,e)=>[o,P(o,e,t)+1.2,e];for(let o=-5;o<=8;o++){const e=y(o,0,t).x0-i;if(e<n||e>a)continue;const f=A(e,t)+40;for(const h of[-4,4]){const p=c(e+h,s),u=c(e+h,f);h>0?r(p,u):r(u,p)}}for(let o=0;o>=-8;o--){const e=y(0,o,t).z0-i;if(e>s)continue;let f=n,h=a;for(;f<h&&!M(f,e,t);)f+=10;for(;h>f&&!M(h,e,t);)h-=10;for(const p of[-4,4]){const u=c(f,e+p),m=c(h,e+p);p>0?r(u,m):r(m,u)}}return l}export function carFleet(t=carLanes(),n=20260928){const a=d(n),s=t.map(o=>Math.hypot(o.b[0]-o.a[0],o.b[2]-o.a[2])),i=s.reduce((o,e)=>o+e,0),[l,r]=LIFE.cars.speed,c=[];for(let o=0;o<LIFE.cars.count;o++){let e=a()*i,f=0;for(;e>s[f]&&f<t.length-1;)e-=s[f++];const{a:h,b:p}=t[f],u=p[2]<h[2]||p[2]===h[2]&&p[0]>h[0];c.push({lane:f,start:a(),speed:l+a()*(r-l),length:s[f],red:u})}return c}export function carPositions(t,n,a,s=new Float32Array(t.length*3)){return t.forEach((i,l)=>{const{a:r,b:c}=n[i.lane],o=((i.start+a*i.speed/i.length)%1+1)%1;s[l*3]=r[0]+(c[0]-r[0])*o,s[l*3+1]=r[1]+(c[1]-r[1])*o,s[l*3+2]=r[2]+(c[2]-r[2])*o}),s}export function drift(t,n,a){const s=LIFE.wind*t.getTime()/1e3/a;return{clouds:[s%1,s*.35%1],ripple:[n*LIFE.ripple[0]%1,n*LIFE.ripple[1]%1]}}
